1        static int blosc_d(
       2            struct thread_context* thread_context, int32_t bsize,
       3            int32_t leftoverblock, const uint8_t* src, int32_t srcsize, int32_t src_offset,
       4            int32_t nblock, uint8_t* dest, int32_t dest_offset, uint8_t* tmp, uint8_t* tmp2) {
       5          blosc2_context* context = thread_context->parent_context;
       6          uint8_t* filters = context->filters;
       7          uint8_t *tmp3 = thread_context->tmp4;
       8          int32_t compformat = (context->header_flags & (uint8_t)0xe0) >> 5u;
       9          int dont_split = (context->header_flags & (uint8_t)0x10) >> 4u;
      10          //uint8_t blosc_version_format = src[BLOSC2_CHUNK_VERSION];
      11          int nstreams;
      12          int32_t neblock;
      13          int32_t nbytes;                /* number of decompressed bytes in split */
      14          int32_t cbytes;                /* number of compressed bytes in split */
      15          int32_t ctbytes = 0;           /* number of compressed bytes in block */
      16          int32_t ntbytes = 0;           /* number of uncompressed bytes in block */
      17          uint8_t* _dest;
      18          int32_t typesize = context->typesize;
      19          const char* compname;
      20
      21          if (context->block_maskout != NULL && context->block_maskout[nblock]) {
      22            // Do not decompress, but act as if we successfully decompressed everything
      23            return bsize;
      24          }
      25
      26          bool is_lazy = context->blosc2_flags & 0x08u;
      27          if (is_lazy) {
      28            // The chunk is on disk, so just lazily load the block
      29            if (context->schunk == NULL) {
      30              BLOSC_TRACE_ERROR("Lazy chunk needs an associated super-chunk.");
      31              return -11;
      32            }
      33            if (context->schunk->frame == NULL) {
      34              BLOSC_TRACE_ERROR("Lazy chunk needs an associated frame.");
      35              return -12;
      36            }
      37            char *fname = context->schunk->frame->fname;
      38            int32_t trailer_len = sizeof(int32_t) + sizeof(int64_t) + context->nblocks * sizeof(int32_t);
      39            int32_t non_lazy_chunklen = srcsize - trailer_len;
      40            // The offset of the actual chunk is in the trailer
      41            int64_t chunk_offset = *(int64_t*)(src + non_lazy_chunklen + sizeof(int32_t));
      42            // Get the csize of the nblock
      43            int32_t *block_csizes = (int32_t *)(src + non_lazy_chunklen + sizeof(int32_t) + sizeof(int64_t));
      44            int32_t block_csize = block_csizes[nblock];
      45            // Read the lazy block on disk
      46            FILE* fp = fopen(fname, "rb");
      47            // The offset of the block is src_offset
      48            fseek(fp, chunk_offset + src_offset, SEEK_SET);
      49            size_t rbytes = fread((void*)(src + src_offset), 1, block_csize, fp);
      50            fclose(fp);
      51            if (rbytes != block_csize) {
      52              BLOSC_TRACE_ERROR("Cannot read the (lazy) block out of the fileframe.");
      53              return -13;
      54            }
      55          }
      56
      57          // If the chunk is memcpyed, we just have to copy the block to dest and return
      58          int memcpyed = src[BLOSC2_CHUNK_FLAGS] & (uint8_t)BLOSC_MEMCPYED;
      59          if (memcpyed) {
      60            int32_t chunk_nbytes = *(int32_t*)(src + BLOSC2_CHUNK_NBYTES);
      61            int32_t chunk_cbytes = *(int32_t*)(src + BLOSC2_CHUNK_CBYTES);
      62            if (chunk_nbytes + BLOSC_MAX_OVERHEAD != chunk_cbytes) {
      63              return -1;
      64            }
      65            int bsize_ = leftoverblock ? chunk_nbytes % context->blocksize : bsize;
      66            if (chunk_cbytes < BLOSC_MAX_OVERHEAD + (nblock * context->blocksize) + bsize_) {
      67              /* Not enough input to copy block */
      68              return -1;
      69            }
      70            memcpy(dest + dest_offset, src + BLOSC_MAX_OVERHEAD + nblock * context->blocksize, bsize_);
      71            return bsize_;
      72          }
      73
      74          if (src_offset <= 0 || src_offset >= srcsize) {
      75            /* Invalid block src offset encountered */
      76            return -1;
      77          }
      78
      79          src += src_offset;
      80          srcsize -= src_offset;
      81
      82          int last_filter_index = last_filter(filters, 'd');
      83
      84          if ((last_filter_index >= 0) &&
      85                  (next_filter(filters, BLOSC2_MAX_FILTERS, 'd') != BLOSC_DELTA)) {
      86           // We are making use of some filter, so use a temp for destination
      87           _dest = tmp;
      88          } else {
      89            // If no filters, or only DELTA in pipeline
      90           _dest = dest + dest_offset;
      91          }
      92
      93          /* The number of compressed data streams for this block */
      94          if (!dont_split && !leftoverblock && !context->use_dict) {
      95            // We don't want to split when in a training dict state
      96            nstreams = (int32_t)typesize;
      97          }
      98          else {
      99            nstreams = 1;
     100          }
     101
     102          neblock = bsize / nstreams;
     103          for (int j = 0; j < nstreams; j++) {
     104            if (srcsize < sizeof(int32_t)) {
     105              /* Not enough input to read compressed size */
     106              return -1;
     107            }
     108            srcsize -= sizeof(int32_t);
     109            cbytes = sw32_(src);      /* amount of compressed bytes */
     110            if (cbytes > 0) {
     111              if (srcsize < cbytes) {
     112                /* Not enough input to read compressed bytes */
     113                return -1;
     114              }
     115              srcsize -= cbytes;
     116            }
     117            src += sizeof(int32_t);
     118            ctbytes += (int32_t)sizeof(int32_t);
     119
     120            /* Uncompress */
     121            if (cbytes == 0) {
     122              // A run of 0's
     123              memset(_dest, 0, (unsigned int)neblock);
     124              nbytes = neblock;
     125            }
     126            else if (cbytes < 0) {
     127              // A negative number means some encoding depending on the token that comes next
     128              uint8_t token = src[0];
     129              src += 1;
     130              ctbytes += 1;
     131              if (token & 0x1) {
     132                // A run of bytes that are different than 0
     133                if (cbytes < -255) {
     134                  // Runs can only encode a byte
     135                  return -2;
     136                }
     137                uint8_t value = -cbytes;
     138                memset(_dest, value, (unsigned int) neblock);
     139                nbytes = neblock;
     140                cbytes = 0;  // everything is encoded in the cbytes token
     141              }
     142            }
     143            else if (cbytes == neblock) {
     144              memcpy(_dest, src, (unsigned int)neblock);
     145              nbytes = (int32_t)neblock;
     146            }
